package net.officefloor.hq.app.plan;

import java.sql.Date;
import java.sql.PreparedStatement;
import java.sql.Statement;
import java.sql.Types;
import java.time.LocalDate;
import java.util.List;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.jdbc.core.RowMapper;
import org.springframework.jdbc.support.GeneratedKeyHolder;
import org.springframework.stereotype.Repository;

/** The plan store: each sheet's plans in the order they were added, and the plan dates each has made a claim for. */
@Repository
public class Plans {

    private static final String SELECT = "SELECT p.id, p.sheet_id, p.person_id, p.amount, p.start_date, p.every_days, p.month_day, p.end_date,"
            + " (SELECT COUNT(*) FROM plan_claim c WHERE c.plan_id = p.id) AS generated FROM plan p";

    private static final RowMapper<Plan> ROW = (rs, n) -> new Plan(rs.getLong("id"), rs.getString("sheet_id"), rs.getLong("person_id"),
            rs.getBigDecimal("amount").setScale(2), rs.getDate("start_date").toLocalDate(), rs.getObject("every_days", Integer.class),
            rs.getObject("month_day", Integer.class), rs.getDate("end_date").toLocalDate(), rs.getInt("generated"));

    private final JdbcTemplate jdbc;

    public Plans(JdbcTemplate jdbc) {
        this.jdbc = jdbc;
    }

    /** The sheet's plans, in the order they were added. */
    public List<Plan> list(String sheetId) {
        return jdbc.query(SELECT + " WHERE p.sheet_id = ? ORDER BY p.id", ROW, sheetId);
    }

    public Plan find(long id) {
        return jdbc.query(SELECT + " WHERE p.id = ?", ROW, id).stream().findFirst().orElse(null);
    }

    public Plan add(String sheetId, long personId, java.math.BigDecimal amount, LocalDate start, Integer every, Integer day, LocalDate end) {
        GeneratedKeyHolder keys = new GeneratedKeyHolder();
        jdbc.update(con -> {
            PreparedStatement ps = con.prepareStatement(
                    "INSERT INTO plan (sheet_id, person_id, amount, start_date, every_days, month_day, end_date) VALUES (?, ?, ?, ?, ?, ?, ?)",
                    Statement.RETURN_GENERATED_KEYS);
            ps.setString(1, sheetId);
            ps.setLong(2, personId);
            ps.setBigDecimal(3, amount);
            ps.setDate(4, Date.valueOf(start));
            ps.setObject(5, every, Types.INTEGER);
            ps.setObject(6, day, Types.INTEGER);
            ps.setDate(7, Date.valueOf(end));
            return ps;
        }, keys);
        return find(keys.getKey().longValue());
    }

    /** Whether the plan has made its claim for the date. */
    public boolean made(long planId, LocalDate date) {
        Integer n = jdbc.queryForObject("SELECT COUNT(*) FROM plan_claim WHERE plan_id = ? AND claim_date = ?", Integer.class,
                planId, Date.valueOf(date));
        return n != null && n > 0;
    }

    /** Records that the plan made the claim for the date. */
    public void recordMade(long planId, LocalDate date, long claimId) {
        jdbc.update("INSERT INTO plan_claim (plan_id, claim_date, claim_id) VALUES (?, ?, ?)", planId, Date.valueOf(date), claimId);
    }
}
package net.officefloor.hq.app.plan;

import java.util.List;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;

/** The sheet's plans, in the order they were added. */
public class LoadPlans {
    public void service(@PathVariable("sheetId") String sheetId, Plans plans, ObjectResponse<List<PlanResponse>> response) {
        response.send(plans.list(sheetId).stream().map(PlanResponse::from).toList());
    }
}
package net.officefloor.hq.app.plan;

/** A plan as the screen shows it (amount with two decimals, dates as yyyy-mm-dd; every or day, the other null). */
public record PlanResponse(String id, String personId, String amount, String start, Integer every, Integer day, String end, int generated) {
    public static PlanResponse from(Plan p) {
        return new PlanResponse(String.valueOf(p.id()), String.valueOf(p.personId()), p.amount().toPlainString(), p.start().toString(),
                p.every(), p.day(), p.end().toString(), p.generated());
    }
}
package net.officefloor.hq.app.plan;

import java.math.BigDecimal;
import java.time.LocalDate;
import java.time.YearMonth;
import java.util.ArrayList;
import java.util.List;

/** A person's plan: the amount, from the start every N days (or monthly on a day of the month) up to the end; generated is
 *  how many claims it has made. Exactly one of every and day is set. */
public record Plan(long id, String sheetId, long personId, BigDecimal amount, LocalDate start, Integer every, Integer day, LocalDate end,
        int generated) {

    /** The plan dates up to and including last: the start then every N days, or the day in every month from the start's month
     *  (on the month's last day when the month is shorter), dates before the start left out. */
    public List<LocalDate> dates(LocalDate last) {
        List<LocalDate> dates = new ArrayList<>();
        if (day != null) {
            for (YearMonth month = YearMonth.from(start); ; month = month.plusMonths(1)) {
                LocalDate date = month.atDay(Math.min(day, month.lengthOfMonth()));
                if (date.isAfter(last)) break;
                if (!date.isBefore(start)) dates.add(date);
            }
        } else {
            for (LocalDate date = start; !date.isAfter(last); date = date.plusDays(every)) {
                dates.add(date);
            }
        }
        return dates;
    }
}
package net.officefloor.hq.app.claim;

import java.time.LocalDate;
import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.holiday.Holidays;
import net.officefloor.hq.app.period.Periods;
import net.officefloor.hq.app.person.People;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.plan.GenerateRequest;
import net.officefloor.hq.app.plan.GenerateResponse;
import net.officefloor.hq.app.plan.Plan;
import net.officefloor.hq.app.plan.Plans;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupFigures;
import net.officefloor.hq.app.setting.Settings;
import net.officefloor.hq.app.setting.ViewerRefusedException;
import net.officefloor.hq.app.sheet.Sheets;
import net.officefloor.plugin.variable.Val;
import net.officefloor.web.ObjectResponse;
import org.springframework.web.bind.annotation.PathVariable;
import org.springframework.web.bind.annotation.RequestBody;

/**
 * For every plan on the sheet, in the order they were added, makes a DRAFT claim of the plan's amount for each plan date (the
 * start, then every N days; or the day in every month from the start's month, on the month's last day when it is shorter,
 * dates before the start left out) up to the end and the sheet's today that has none yet, dated that day with an empty note, each
 * audited as CLAIM_ADDED. A date the claim form refuses (its due-by inside a closed period, after the person's retirement) is
 * skipped, and tried again on the next generate.
 */
public class GeneratePlanClaims {
    public void generate(@PathVariable("sheetId") String sheetId, @RequestBody GenerateRequest request, Plans plans, People people,
            Claims claims, Sheets sheets, Periods periods, Holidays holidays, Settings settings, ClaimLog log, Audit audit,
            @Val RollupFigures before, Rollup rollup, ObjectResponse<GenerateResponse> response) throws ViewerRefusedException {
        settings.refuseViewer(sheetId, request.user());
        LocalDate today = sheets.today(sheetId);
        int made = 0;
        for (Plan plan : plans.list(sheetId)) {
            Person person = people.find(sheetId, plan.personId());
            if (person == null) continue;
            LocalDate last = plan.end().isBefore(today) ? plan.end() : today;
            for (LocalDate date : plan.dates(last)) {
                if (plans.made(plan.id(), date)) continue;
                LocalDate dueBy = holidays.dueBy(sheetId, date, settings.termsFor(sheetId, person.getTerms(), person.gradeOn(date), date));
                if (periods.isClosed(sheetId, dueBy) || !person.allowsClaimOn(date)) continue;
                Claim claim = claims.add(sheetId, person.getId(), plan.amount(), date, "", null, dueBy, null);
                plans.recordMade(plan.id(), date, claim.getId());
                log.record(claim, person, request.user());
                audit.recordOnCommit(ClaimAudit.added(request.user(), person, claim));
                LateEntry.mark(claim, person, request.user(), claims, periods, audit);
                made++;
            }
        }
        rollup.recordChanges(sheetId, request.user(), before);
        response.send(new GenerateResponse(made));
    }
}
